export const SUM_SOURCE = "    MOV R0, 0\n    MOV R1, 0\n    MOV R15, 0\n    MOV R11, 1\n    MOV R4, 0x0101\n    LD R3, [0x0100]\n    CMP R3, R15\n    JZ done\nloop:\n    LD R6, [R4]\n    SAR R7, R6, 15       ; расширить знак до старшего слова\n    ADD R0, R0, R6\n    ADC R1, R1, R7       ; перенос от младшего слова\n    ADD R4, R4, R11\n    SUB R3, R3, R11\n    JNZ loop            ; флаг нуля от уменьшения счётчика\ndone:\n    ST [0x0300], R0\n    ST [0x0301], R1\n    HALT\n";
export const DOT_SOURCE = "    MOV R0, 0\n    MOV R1, 0\n    MOV R2, 0\n    MOV R11, 1\n    MOV R12, 10\n    MOV R14, 0\n    LD R3, [0x0100]\n    CMP R3, R12\n    JNZ invalid_length\n    LD R13, [0x0200]\n    CMP R13, R12\n    JNZ invalid_length\n    MOV R4, 0x0101\n    MOV R5, 0x0201\nloop:\n    LD R6, [R4]\n    LD R7, [R5]\n    MULLO R8, R6, R7\n    MULHI R9, R6, R7\n    SAR R10, R9, 15      ; знак произведения в третье слово\n    ADD R0, R0, R8\n    ADC R1, R1, R9\n    ADC R2, R2, R10\n    ADD R4, R4, R11\n    ADD R5, R5, R11\n    SUB R3, R3, R11\n    JNZ loop\n    ST [0x0300], R0\n    ST [0x0301], R1\n    ST [0x0302], R2\n    ST [0x0303], R14\n    HALT\ninvalid_length:\n    MOV R14, 1\n    ST [0x0303], R14\n    HALT\n";
